// Attendu en entrée : { prompt, system, model_hint }
// model_hint : 'fast' | 'quality' | 'classify'
const { prompt, system, model_hint } = $input.first().json;

const PROVIDERS = [
  { name: 'groq',     model: model_hint === 'quality' ? 'llama-3.3-70b-versatile' : 'llama-3.1-8b-instant' },
  { name: 'gemini',   model: 'gemini-1.5-flash' },
  { name: 'deepseek', model: 'deepseek-chat' },
  { name: 'openai',   model: 'gpt-4o-mini' }
];

return [{ json: { prompt, system, providers: PROVIDERS, current_index: 0 } }];

const data = $input.first().json;
const provider = data.providers[data.current_index];
return [{ json: { ...data, active_provider: provider } }];

const input = $input.first().json;
// Succès : extraire le texte de la réponse OpenAI-compatible
const text = input?.choices?.[0]?.message?.content ?? null;
if (!text) throw new Error('Empty response from provider');
return [{ json: { result: text, provider_used: 'success' } }];

// Fallback : incrémenter l'index et réessayer avec le prochain fournisseur
const data = $('Pick Provider').first().json;
const next = data.current_index + 1;
if (next >= data.providers.length) {
  throw new Error('All AI providers failed');
}
return [{ json: { ...data, current_index: next } }];

const f = $input.first().json;
const required = ['Nom complet', 'Email', 'Téléphone / WhatsApp', 'Ville recherchée', 'Poste recherché'];
for (const field of required) {
  if (!f[field]) throw new Error(`Champ manquant : ${field}`);
}
return [{ json: {
  full_name: f['Nom complet'],
  email: f['Email'].toLowerCase().trim(),
  phone: f['Téléphone / WhatsApp'],
  whatsapp_number: f['Téléphone / WhatsApp'],
  city: f['Ville recherchée'],
  target_role: f['Poste recherché'],
  has_cv: !!f['CV (PDF ou Word)']
}}];

const raw = $input.first().json.result;
try {
  const parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
  return [{ json: { structured: parsed } }];
} catch(e) {
  throw new Error('AI did not return valid JSON: ' + raw.substring(0, 200));
}

const { titles, companies, cities, links } = $input.first().json;
const offers = (titles || []).map((title, i) => ({
  source: 'camerjob',
  external_id: (links?.[i] || '').split('/').pop() || `camerjob-${i}`,
  title: title?.trim(),
  company: companies?.[i]?.trim() || null,
  city: cities?.[i]?.trim() || null,
  contact_email: null,
  raw_data: JSON.stringify({ title, company: companies?.[i], city: cities?.[i], url: links?.[i] })
})).filter(o => o.title);
return offers.map(o => ({ json: o }));

// Filtre dur : ville + contact email présent
const item = $input.first().json;
const profile = JSON.parse(item.profile || '{}');
const cityMatch = !profile.city || (item.city || '').toLowerCase().includes(profile.city.toLowerCase());
const hasContact = !!item.contact_email;
if (!cityMatch || !hasContact) {
  return [{ json: { ...item, score: 0, rejected: true, reject_reason: !cityMatch ? 'city_mismatch' : 'no_contact' } }];
}
return [{ json: { ...item, score: 50, rejected: false } }];

const ai = $input.first().json;
try {
  const parsed = JSON.parse(ai.result.replace(/```json|```/g, '').trim());
  return [{ json: { score: parsed.score, reason: parsed.reason } }];
} catch { return [{ json: { score: 60, reason: 'parse_error' } }]; }

