// Normalise le numéro : retire +, espaces, ajoute 237 si numéro camerounais sans indicatif
let num = ($input.first().json.whatsapp_number || '').replace(/[^0-9]/g, '');
if (num.startsWith('0')) num = '237' + num.substring(1);
if (!num.startsWith('237') && num.length === 9) num = '237' + num;
return [{ json: { to: num, message: $('Execute Workflow Trigger').first().json.message } }];
